cd /home/anthoni/projects/kyverno-spike; date; export LC_ALL=C; mkdir -p out/rendered out/render-logs; : > out/render-summary.tsv
slug(){ echo "$1" | tr '/' '_'; }
for repo in microservices-demo argocd-example-apps examples kubernetes-goat; do mkdir -p out/rendered/$repo; 
 for c in $(find $repo -name Chart.yaml | sort); do d=$(dirname $c); s=helm__$(slug $d); 
   helm template rel $d > out/rendered/$repo/$s.yaml 2> out/render-logs/$s.err; rc=$?; echo -e "helm\t$d\t$rc\t$(grep -c '^kind:' out/rendered/$repo/$s.yaml)" >> out/render-summary.tsv; done
 for k in $(find $repo \( -name kustomization.yaml -o -name kustomization.yml -o -name Kustomization \) | sort); do d=$(dirname $k); s=kust__$(slug $d);
   kustomize build $d > out/rendered/$repo/$s.yaml 2> out/render-logs/$s.err; rc=$?; echo -e "kustomize\t$d\t$rc\t$(grep -c '^kind:' out/rendered/$repo/$s.yaml)" >> out/render-summary.tsv; done
done; cat out/render-summary.tsv

